def solve():
    supply = P["SUPPLY"] * 1000000
    bal = {"A": P["BAL_A"], "B": P["BAL_B"], "C": P["BAL_C"]}
    out = {"A": 20000, "B": P["OUT_B"], "C": 0}
    if bal["A"] + bal["B"] + bal["C"] > supply:
        raise ValueError("combined address balances exceed circulating supply")
    combined = bal["A"] + bal["B"] + bal["C"]
    thr = combined * P["BAL_PCT"] / 100
    out_thr = P["OUT_THRESH"]
    cold = P["COLD"]
    whales = []
    for k in ("A", "B", "C"):
        if k == cold:
            continue
        if bal[k] > thr or out[k] > out_thr:
            whales.append(k)
    count = len(whales)
    total = 0
    for k in whales:
        total = total + bal[k]
    share = total / supply * 100
    return {"final": share, "balance_threshold": thr, "whale_count": count, "total_whale_balance": total}
